import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from ficha import *
T="SEPSIS"; N=7
note=lambda t: f'<div style="font-size:36px;line-height:1.4;color:{G}">{t}</div>'
rows=lambda *x: '<div style="display:flex;flex-direction:column;gap:22px">'+"".join(x)+'</div>'
P=[
page(1,N,T,big("SEPSIS",250,nowrap=True)+big(f'LA PRIMERA HORA <span style="color:{R}">MANDA</span>',132)+'<div style="font-size:40px;font-weight:600;line-height:1.3;max-width:820px">Qué hacer y en qué orden según la guía internacional de 2026. Con ficha final para guardar.</div>',cover=True),
page(2,N,T,kicker("PASO 1 · SOSPECHA")+big("CRIBA CON UNA ESCALA",112)+rows(line("NEWS, NEWS2, MEWS o SIRS",True),line("El qSOFA, por sí solo, no sirve como cribado"),line("Busca hipoperfusión: hipotensión, lactato elevado, relleno capilar lento"))+note("La sepsis y el shock séptico son emergencias: el tratamiento empieza de inmediato.")),
page(3,N,T,kicker("PASO 2 · ANTIBIÓTICO")+big("EN 1 HORA",200,R,True)+rows(row("Shock o sepsis probable","≤ 1 h"),row("Sepsis posible, sin shock","≤ 3 h"),row("Sin foco","Ceftriaxona"),row("Sanitaria o multirresistentes","Ceftriaxona + amikacina o pip-tazo"),row("Shock séptico","Meropenem + vancomicina ± amikacina"))+note("Hemocultivos antes, sin retrasarlo. Con foco conocido, la pauta del foco. Ajusta a la guía de tu hospital.")),
page(4,N,T,kicker("PASO 3 · FLUIDOS")+big("30 ML/KG",230,R,True)+'<div style="font-size:48px;font-weight:800;line-height:1.2">De cristaloide, en las 3 primeras horas, si hay hipoperfusión o shock</div>'+rows(row("Tipo","Balanceado (Ringer lactato) antes que salino 0,9 %"),row("Si IMC &gt; 30","Calcula con peso ajustado o ideal"))+note("Es un mínimo orientativo: reevalúa e individualiza con medidas dinámicas.")),
page(5,N,T,kicker("PASO 4 · VASOPRESOR")+big("NORADRENALINA",140,R,True)+rows(row("Preparación","10 mg en 50 ml de G5 % = 200 µg/ml"),row("Inicio","0,05–0,15 µg/kg/min"),row("Objetivo","PAM 65 (60–65 si ≥ 65 años)"),line("Por vía periférica si hace falta: no esperes a la central"),row("Shock que persiste","Hidrocortisona 50 mg/6 h IV"),row("Si no responde","Avisa a UCI"))),
page(6,N,T,kicker("Y NO OLVIDES")+big("CONTROLA EL FOCO",128)+rows(line("Drenar, desobstruir o retirar el dispositivo infectado cuanto antes",True),line("Desescala el antibiótico cuando llegue el antibiograma"),line("Pasada la reanimación, retira el exceso de líquido"))+note("El antibiótico sin control del foco no resuelve la sepsis.")),
page(7,N,T,ficha_body("SEPSIS","Adulto",[("CRIBADO","NEWS2, NEWS, MEWS o SIRS. No qSOFA aislado"),("TIEMPO","Antibiótico ≤ 1 h si shock o sepsis probable; ≤ 3 h si posible. Hemocultivos antes"),("ANTIBIÓTICO","Sin foco: ceftriaxona. Sanitaria o multirresistentes: ceftriaxona + amikacina o pip-tazo. Shock: meropenem + vancomicina ± amikacina. Con foco: la pauta del foco",True),("FLUIDOS","Cristaloide balanceado (Ringer lactato) ≥ 30 ml/kg en 3 h si hay hipoperfusión. Reevaluar"),("NORADREN.","10 mg en 50 ml G5 % (200 µg/ml). 0,05–0,15 µg/kg/min, también periférica. PAM 65 (60–65 si ≥ 65 años)"),("SI PERSISTE","Hidrocortisona 50 mg/6 h IV. Avisa a UCI",True),("FOCO","Control del foco precoz")],"Prescott HC, et al. Surviving Sepsis Campaign 2026. Crit Care Med 2026; Guía antimicrobiana HU Puerta del Mar (antibióticos)",size=105,fs=27),ficha="06"),
]
render(P,sys.argv[1] if len(sys.argv)>1 else "out","sepsis")
